	background-color: #3f444d;
	color: white;
	border: none;
	padding: 5px 10px;
	border-radius: 4px;
	margin-right: 10px;
	cursor: pointer;
}

input[type="file"]::file-selector-button:hover {
	background-color: #4f555e;
}

/* Ajuste para o calendário (Data) e Relógio (Hora) ficarem no modo escuro */
input[type="date"], input[type="time"] {
	color-scheme: dark;
}

