let listaDeDados = [];

// 1. Tenta pegar os dados do nó 'Aggregate'
try {
  const itemAgrupado = $('Aggregate XLSX').first();
  listaDeDados = itemAgrupado?.json?.data || [];
} catch (erro) {
  // Se der erro (porque o nó 'Aggregate' não rodou no fluxo), o código não trava. 
  // Ele apenas ignora e continua.
}

// 2. Se a lista ainda estiver vazia (porque o primeiro não rodou ou não tinha dados), tenta o segundo
if (listaDeDados.length === 0) {
  try {
    const itemAgrupado1 = $('Aggregate CSV').first();
    listaDeDados = itemAgrupado1?.json?.data || [];
  } catch (erro) {
    // Também ignora se o 'Aggregate1' não tiver rodado
  }
}

// Se nenhum dos dois gerou dados, encerra retornando vazio para não quebrar o próximo nó
if (listaDeDados.length === 0) {
  return [];
}

// 3. Mapeia a lista vencedora para o formato padrão que o n8n exige [{ json: { ... } }]
return listaDeDados.map(item => {
  return {
    json: item
  };
});

