    color: #00ff9d !important; /* Texto em verde neon */
    font-size: 12px !important;
    line-height: 1.6;
    margin-bottom: 25px;
    white-space: pre-wrap; /* Mantém as quebras de linha da sua lista */
}

/* --- CHECKBOX CUSTOMIZADO --- */

input[type="checkbox"] {
    accent-color: #00ff9d; /* Checkbox fica verde neon ao marcar */
    width: 18px;
    height: 18px;
    cursor: pointer;
    vertical-align: middle;
}

/* --- FIX DE VISIBILIDADE DO INPUT DE TEXTO --- */

input[type="text"] {
    background-color: #24292e !important;
    color: #ffffff !important;
    border: 1px solid var(--color-input-border) !important;
    padding: 12px !important;
}

input[type="text"]:focus {
    border-color: #00ff9d !important;
    box-shadow: 0 0 8px rgba(0, 255, 157, 0.2);
    outline: none;
}

